package com.ptms.service;import com.ptms.domain.*;import com.ptms.dto.*;import com.ptms.exception.*;import com.ptms.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @Transactional public class TicketIssueService{private final TicketIssueRepository ir;private final ParkingTicketRepository tr;private final EmployeeRepository er;private final VisitorRepository vr;private final ParkingDurationService ds;private final TicketCombinationService cs;public TicketIssueService(TicketIssueRepository ir,ParkingTicketRepository tr,EmployeeRepository er,VisitorRepository vr,ParkingDurationService ds,TicketCombinationService cs){this.ir=ir;this.tr=tr;this.er=er;this.vr=vr;this.ds=ds;this.cs=cs;}public IssuePreviewResponse preview(IssuePreviewRequest q){boolean pass=false;if(q.personType()==PersonType.EMPLOYEE)pass=er.findByEmployeeCode(q.personReference()).orElseThrow(()->new ResourceNotFoundException("Employee not found")).isParkingPass();else vr.findByVisitorCode(q.personReference()).orElseThrow(()->new ResourceNotFoundException("Visitor not found"));int h=ds.requiredTicketHours(q.personType(),pass,q.visitDate(),q.entryTime(),q.exitTime(),q.extraHours());List<List<Integer>> available=cs.combinationsFor(h).stream().filter(this::inventoryCanSupply).toList();if(h>0&&available.isEmpty())throw new BusinessRuleException("No available ticket combination can cover "+h+" hour(s) with current inventory");return new IssuePreviewResponse(h,available);}private boolean inventoryCanSupply(List<Integer> combo){Map<Integer,Long>need=new HashMap<>();combo.forEach(x->need.merge(x,1L,Long::sum));return need.entrySet().stream().allMatch(e->tr.countByStatusAndDurationHours(TicketStatus.AVAILABLE,e.getKey())>=e.getValue());}public IssueResponse create(CreateIssueRequest q){IssuePreviewResponse p=preview(new IssuePreviewRequest(q.personType(),q.personReference(),q.visitDate(),q.entryTime(),q.exitTime(),q.extraHours()));if(q.selectedCombination().stream().mapToInt(Integer::intValue).sum()!=p.requiredHours()||!p.combinations().contains(q.selectedCombination()))throw new BusinessRuleException("Invalid or unavailable ticket combination");if(new HashSet<>(q.barcodes().stream().map(String::toLowerCase).toList()).size()!=q.barcodes().size())throw new BusinessRuleException("Duplicate barcode in request");if(q.barcodes().size()!=q.selectedCombination().size())throw new BusinessRuleException("Barcode count mismatch");List<ParkingTicket>ts=q.barcodes().stream().map(b->tr.findByBarcodeIgnoreCase(b).orElseThrow(()->new ResourceNotFoundException("Barcode not found: "+b))).toList();if(ts.stream().anyMatch(t->t.getStatus()!=TicketStatus.AVAILABLE))throw new BusinessRuleException("All tickets must be available");if(ts.stream().anyMatch(t->t.getExpiryDate()!=null&&t.getExpiryDate().isBefore(q.visitDate())))throw new BusinessRuleException("Expired ticket cannot be issued");List<Integer>a=ts.stream().map(ParkingTicket::getDurationHours).sorted().toList(),e=q.selectedCombination().stream().sorted().toList();if(!a.equals(e))throw new BusinessRuleException("Scanned ticket types do not match combination");TicketIssue i=new TicketIssue();i.setRequestNumber("REQ-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());i.setPersonType(q.personType());i.setPersonReference(q.personReference());i.setVisitDate(q.visitDate());i.setEntryTime(q.entryTime());i.setExitTime(q.exitTime());i.setExtraHours(q.extraHours()==null?0:q.extraHours());i.setRequiredHours(p.requiredHours());i.setReason(q.reason());ts.forEach(i::addTicket);return dto(ir.save(i));}public IssueResponse complete(Long id){TicketIssue i=ir.findById(id).orElseThrow();if(i.getStatus()!=IssueStatus.PENDING)throw new BusinessRuleException("Only pending requests can be completed");LocalDateTime now=LocalDateTime.now();for(TicketIssueItem x:i.getItems()){ParkingTicket t=x.getTicket();if(t.getStatus()!=TicketStatus.AVAILABLE)throw new BusinessRuleException("Ticket no longer available");t.setStatus(TicketStatus.ISSUED);t.setIssuedAt(now);t.setIssuedToReference(i.getPersonReference());}i.setStatus(IssueStatus.COMPLETED);i.setCompletedAt(now);return dto(ir.save(i));}public void delete(Long id){TicketIssue i=ir.findById(id).orElseThrow();if(i.getStatus()!=IssueStatus.PENDING)throw new BusinessRuleException("Completed request cannot be deleted");ir.delete(i);}public List<IssueResponse>all(){return ir.findAllByOrderByCreatedAtDesc().stream().map(this::dto).toList();}private IssueResponse dto(TicketIssue i){return new IssueResponse(i.getId(),i.getRequestNumber(),i.getPersonType(),i.getPersonReference(),i.getVisitDate(),i.getEntryTime(),i.getExitTime(),i.getExtraHours(),i.getRequiredHours(),i.getReason(),i.getStatus(),i.getCreatedAt(),i.getCompletedAt(),i.getItems().stream().map(x->x.getTicket().getBarcode()).toList());}}
